module freq_divbyfrac #(
    parameter MUL2_DIV_CLK = 7
) (
    input               rst_n,
    input               clk,
    output              clk_div
);

    reg [3:0] cnt;
    reg clk_div_int;
    reg phase_shift_clk;
    reg phase_shift_clk_delay;
    reg phase_shift_clk_advance;
    always@(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            cnt <= 0;
            clk_div_int <= 0;
            phase_shift_clk <= 0;
            phase_shift_clk_delay <= 0;
            phase_shift_clk_advance <= 0;
        end
        else begin
            if(cnt == 7) begin
                cnt <= 0;
            end
            else begin
                cnt <= cnt + 1;
            end

            if(cnt < 4) begin
                clk_div_int <= ~clk_div_int;
            end

            case(cnt)
                2: phase_shift_clk <= ~clk_div_int;
                4: phase_shift_clk_delay <= ~clk_div_int;
                6: phase_shift_clk_advance <= ~clk_div_int;
                default: ;
            endcase
        end
    end
    assign clk_div = phase_shift_clk | phase_shift_clk_delay | phase_shift_clk_advance;
endmodule
